from dataclasses import dataclass


@dataclass(frozen=True)
class EgressPolicy:
    allow_tailnet: bool = False

    def permits(self, dest):
        return self.allow_tailnet or not dest.endswith('.mesh.invalid')


def policy_for(client_id, table):
    return table.get(client_id, EgressPolicy())

class HomeTransport:
    def __init__(self, links, egress_policy=None):
        self.links = links
        self.egress_policy = egress_policy

    def send(self, packet):
        if self.egress_policy is not None and not self.egress_policy.permits(packet.dest):
            return None
        return self.links[0].send(packet)

